// The contract between a site file (providers/*.ts) and PlazCode's core (core/main.js). Every site file must provide the
// required members; the optional ones are the extra hooks some sites use. A member not listed here is a typo or a new hook:
// add it here first (TypeScript, step 2, owner 2026-11-15).
type Diag = (name: string, data?: object) => void;
interface ImagePayload { mimeType?: string; data: string; name?: string; size?: number; kind?: string; [extra: string]: unknown }
interface ImagePayloadList extends Array<ImagePayload> { __rsId?: string | number }
interface AssistantRead { present: boolean; reply: string; thinking: string; item: Element | null; [extra: string]: unknown }
interface SendHooks { isBlocked(): boolean; isStarted(): boolean; onBlockedAttempt(): void; onUserMessage(count: number, token?: any): void; onNativeStop(): void; onCoworkSend?(event: any): boolean; [extra: string]: unknown }
interface PlazCodeProvider {
  id: string;
  displayName: string;
  supportsVision: boolean;
  timings: Record<string, number>;
  init: (options?: { diag?: Diag; [hook: string]: any }) => void;
  allItems: () => Element[];
  isUserItem: (item: Element) => boolean;
  isAssistantItem: (item: Element) => boolean;
  itemText: (item: Element) => string;
  classifyText: (item: Element, excludeSel?: string) => string;
  assistantCount: () => number;
  userCount: () => number;
  lastAssistant: () => Element | null;
  readAssistant: () => AssistantRead;
  streamLen: (item?: Element | null) => number;
  snapshot: () => object;
  getEditor: () => HTMLElement | null;
  editorText: (el?: any) => string;
  chatIsEmpty: () => boolean;
  isFreshChat: () => boolean;
  composerFrame: () => Element | null;
  barAnchor: () => Element | null;
  setInputLock: (on: boolean) => void;
  typeAndSend: (text: string, images?: ImagePayloadList, options?: object) => Promise<boolean | void>;
  stopGeneration: () => void;
  isGenerating: () => boolean;
  isBusyNow: () => boolean;
  isHardGenerating: () => boolean;
  enforceComposer: (reason?: string) => unknown;
  ensureComposerReady: (reason?: string) => Promise<{ ready: boolean; detail?: string }>;
  turnHalted: (item?: Element | null) => boolean;
  findContinueBtn: () => Element | null;
  clickContinueBtn: () => boolean | Promise<unknown>;
  scanError: () => string | null;
  isTooLongMsg: (text: string) => boolean;
  isBusyMsg: (text: string) => boolean;
  attachImages: (images: ImagePayloadList) => unknown;
  clearAttachments: () => void;
  conversationKey: () => string;
  installSendHooks: (hooks: SendHooks) => void;
  findToolBlockSpot: (item: Element, chip?: Element) => { parent: Element | null; ref: Element | null } | null;
  // Optional hooks (loosely typed for now; tighten one at a time).
  activeWorkflowProgress?: any;
  activityItemKey?: any;
  alignChip?: any;
  authGatePresent?: any;
  authoritativeSendResult?: any;
  autoResumeUnstarted?: any;
  backgroundAgentSupported?: any;
  barMount?: any;
  barOutside?: any;
  barTrackIntervalMs?: any;
  canRenderImmutableChip?: any;
  canRestoreSession?: any;
  cancelPendingSends?: any;
  captchaPresent?: any;
  chipAnchor?: any;
  chipAppend?: any;
  chipAtItemLevel?: any;
  chipTrailRef?: any;
  clearEditor?: any;
  clearImmutableChip?: any;
  closedToolNoProgressMs?: any;
  collectExportHistory?: any;
  compactStartup?: any;
  confirmedDeliveryMatches?: any;
  conversationAliases?: any;
  coverMaxH?: any;
  coverOffsetY?: any;
  coverPad?: any;
  coverTarget?: any;
  deterministicBootstrapList?: any;
  emptyReplyGraceMs?: any;
  expandCollapsedWork?: any;
  failHardOnSendFailure?: any;
  flatTranscript?: any;
  followupPlaceholderTargets?: any;
  gateTarget?: any;
  genDebug?: any;
  getEditorRaw?: any;
  guardedSender?: any;
  hasPendingAttachment?: any;
  hasRegenerate?: any;
  helperChatUrl?: any;
  ignoreMutationRecords?: any;
  immutableChipOwned?: any;
  immutableChipPresent?: any;
  immutableTranscript?: any;
  invalidateItems?: any;
  isComparisonTurn?: any;
  isPolicyRefusal?: any;
  itemKey?: any;
  lastAssistantId?: any;
  lateStartupReply?: any;
  layoutChanged?: any;
  loginGatePresent?: any;
  meterIntervalMs?: any;
  minSecondsBetweenSends?: any;
  modeWarning?: any;
  mountActivitySummary?: any;
  mutationAttributeFilter?: any;
  name?: any;
  noteHealthyReply?: any;
  noteRateLimit?: any;
  observeCharacterData?: any;
  openNewChat?: any;
  overlayBlocking?: any;
  periodicSweepMs?: any;
  prepareSessionStart?: any;
  preprocessMutations?: any;
  promptExtra?: any;
  reconnectOnEmpty?: any;
  recoverInternalError?: any;
  regenerateEmpty?: any;
  reliableCounts?: any;
  renderImmutableChip?: any;
  renderReadyAcknowledgement?: any;
  replyUnsettled?: any;
  requireConfirmedStartup?: any;
  requireFreshResponse?: any;
  resendSystemEvery?: any;
  reserveBarSpace?: any;
  resolveComparison?: any;
  respectNativeGeneration?: any;
  responsePending?: any;
  responseRemountGraceMs?: any;
  responseSettleMs?: any;
  scanBusy?: any;
  sendBlocker?: any;
  sendButton?: any;
  sendCharBudget?: any;
  sendFailureAmbiguous?: any;
  sendFailureDetail?: any;
  sendLanded?: any;
  sendNotTaken?: any;
  sendRetryable?: any;
  setActivityFolded?: any;
  setFollowupMode?: any;
  settleStartupReply?: any;
  softGenerationSettled?: any;
  startNotice?: any;
  startupCorrection?: any;
  startupEvidence?: any;
  startupFeedbackMessages?: any;
  startupReplyAsCode?: any;
  startupReplySettled?: any;
  startupRequest?: any;
  strictSendReceipt?: any;
  suppressThinkingWatchdog?: any;
  sweepStaleInternalDraft?: any;
  sweepThrottleMs?: any;
  syncHiddenShell?: any;
  syncImmutableChips?: any;
  sysMaxChars?: any;
  textWithout?: any;
  thinkingNoProgressMs?: any;
  thinkingRecoveryLimit?: any;
  thinkingSel?: any;
  thinkingStopWaitMs?: any;
  toolBlockVisible?: any;
  toolFeedbackMaxChars?: any;
  toolResultPageChars?: any;
  turnComplete?: any;
  turnEndedEmpty?: any;
  unstableWarning?: any;
  updateImmutableChipDetail?: any;
  updateImmutableChipLabel?: any;
  userVoiceStartup?: any;
  withTranscriptSnapshot?: any;
  writeDraft?: any;
}
